sin(angle), cos(angle)));
// In GLSL is column-major order and in HLSL, row-major order,
// So we transpose the matrix with transpose() to be the same as GLSL.
p.xy = multiply(p.xy, R);
// Fractal evaluation
N = f(p+q1 / 2.0 + t*0.1);
d = length(p.xy)-1.0+N*0.3;
p.z = mod(p.z,4.0+cos(q6))-3.0;
d = abs(d)+0.01;
// Color composition
vec3 c = vec3(0.1,0.3,0.8)/(length(p.xy+N+audioLowSmooth)*0.8);
c += vec3(0.8,0.4,0.2)/(length(p.xz+N)*0.5);
c += vec3(1.0,1.0,2.0)*(0.5+0.5*sin(N*1.0+t));
// Accumulate color with falloff
o += c/d*0.12;
z += d*0.6;
}

